18| export function formatZodIssues(error: ZodError): string {
19|   return error.issues
20|     .map((issue) => `${issue.path.length > 0 ? issue.path.map(String).join('.') : '(root)'}: ${issue.message}`)
21|     .join('; ');
22| }
23| 
24| export function toHttpProblem(err: unknown): HttpProblem {
25|   if (err instanceof HttpProblem) return err;
26|   if (err instanceof ZodError) return unprocessable(formatZodIssues(err));
27|   const parserError = BodyParserErrorSchema.safeParse(err);
28|   if (parserError.success) {
29|     const { type, status, message } = parserError.data;
30|     if (type === 'entity.parse.failed') return badRequest('The request body is not valid JSON.');
31|     return new HttpProblem({ type: typeUri('request-rejected'), title: 'Request Rejected', status, detail: message });
32|   }
33|   return internalError();
34| }
